def _raster_format(path):
    import hashlib
    import numpy as np
    import rasterio
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    with rasterio.open(path) as s:
        a = s.read(1)
        finite = np.isfinite(a)
        ok = (s.count == 1 and s.dtypes[0] == 'float32' and str(s.crs) == EXPECTED_GRID['crs']
              and (s.height, s.width) == EXPECTED_GRID['shape']
              and tuple(s.transform)[:6] == EXPECTED_GRID['transform']
              and s.nodata is None
              and bool(finite.all()) and float(a.min()) >= 0.0 and float(a.max()) <= 1.0)
    return digest, bool(ok)


def status_board():
    rows = []
    for label, card_path, tif_path, page in BOARD_ROWS:
        card = json.loads((ROOT / card_path).read_text())
        g = gates(card)
        failing = [k for k, v in g.items() if v is not True]
        tif = ROOT / tif_path
        if tif.is_file():
            digest, fmt_ok = _raster_format(tif)
            file_cell = f'<code>{escape(tif_path.split("/")[-1])}</code><br><small>SHA-256 {digest[:16]}…{digest[-8:]}</small>'
            dl = ('<span class="badge">YES · research only</span>' if fmt_ok
                  else '<span class="badge bad">NO · format check failed</span>')
            fmt = 'PASS (re-read from disk)' if fmt_ok else 'FAIL'
            # No download attribute here: the portal may advertise only its current artifact as a download.
            link = f'<a href="{escape(page, quote=True)}">open audit page</a>' if fmt_ok else ''
        else:
            file_cell, dl, fmt, link = '<em>file not present</em>', '<span class="badge bad">NO</span>', 'not checked', ''
        rows.append(
            f'<tr><td>{escape(label)}</td><td>{file_cell}</td><td>{dl} {link}</td><td>{fmt}</td>'
            f'<td><span class="badge bad">NO</span></td><td>{escape(", ".join(failing) or "none")}</td></tr>'
        )
    return (
        '<section class="section" id="status-board" data-status-board="computed"><div class="card">'
        '<span class="eyebrow">STATUS BOARD · COMPUTED FROM FILES AT RENDER TIME</span>'
        '<h2>Can I download it? Can I submit it?</h2>'
        '<p><strong>Download</strong> = a research copy that passed the local format check; it is not a submission. '
        '<strong>Submit</strong> = the shared fail-closed gate (<code>src/gems91/readiness.py</code>) must pass every check, '
        'and a separate selector must verify the current weekly allowance. No file passes that gate today.</p>'
        '<div class="table-scroll"><table><thead><tr><th>Candidate</th><th>File</th><th>OK to download (research)?</th>'
        '<th>Format re-read</th><th>OK to submit?</th><th>Failing shared gates</th></tr></thead><tbody>'
        + ''.join(rows) +
        '</tbody></table></div>'
        '<p><small>Before any download is used: confirm eligibility and data rights (rules §1.3 and A.5). '
        'Separate documented requirements: eligibility, data rights, AI disclosure, lane assignment and selector approval. No visual inspection is used. '
        'A "format" failure on a row means its run card lacks the fields the shared gate reads (IR-91-S12-02); the file itself re-reads PASS.</small></p>'
        '</div></section>'
    )


def s17_cdsc_content(board):
    """Render Session 17 S17-CDSC directly from its fail-closed JSON run card."""
    path = ROOT / 'docs/run-card-S17-CDSC.json'
    if not path.is_file():
        return '', '', ''
    import hashlib
    card = json.loads(path.read_text())
    artifact = card['artifact']
    tif = ROOT / artifact['primary_zeros_tif']
    zip_path = ROOT / artifact['zip_bundle']
    if not tif.is_file() or not zip_path.is_file():
        raise ValueError('S17-CDSC published artifact is missing on disk')
    if hashlib.sha256(tif.read_bytes()).hexdigest() != card['raster_sha256']:
        raise ValueError('S17-CDSC TIFF SHA-256 mismatch')
    if hashlib.sha256(zip_path.read_bytes()).hexdigest() != artifact['zip_sha256']:
        raise ValueError('S17-CDSC ZIP SHA-256 mismatch')
    if card.get('submission_ready') or submission_ready(card):
        raise ValueError('S17-CDSC research artifact must remain fail-closed')

    tif_rel = tif.relative_to(ROOT / 'docs').as_posix()
    zip_rel = zip_path.relative_to(ROOT / 'docs').as_posix()
    h = card['holdout_dti']
    paired = h['paired_best']
    paired_s13 = h['paired_vs_s13_ptha_e3']
    registry = card['registry_comparison']
    reg_sum = registry['summary']
    r0_cmp = reg_sum.get('r0_comparison') or {}
    ext_cmp = reg_sum.get('disaggregated_external_fleet_real_only') or {}
    canary = card['canaries']
    submit = card['submission']
    validator = card['validator_output']
    sgmc = card['blind_sgmc_offcatalogue_control']
    overlap_pct = 100.0 * registry['max_measured_final_dot_overlap_within_3px']
    r0_ov_pct = 100.0 * float(r0_cmp.get('cand_within_3px_of_r0', 0.0))
    ext_ov_pct = 100.0 * float(ext_cmp.get('max_3px_dot_overlap_vs_external_real_submissions', 0.0))
    surface_rho = registry['max_measured_surface_rank_correlation']
    fail_gates = [k for k, v in gates(card).items() if v is not True]

