    h = card['holdout_dti']; a = card.get('artifact'); registry = card['registry_comparison']
    updated = card.get('completed_utc', card.get('started_utc', 'not recorded'))[:19].replace('T',' ')
    interval = '–'.join(f(x) for x in h.get('ci95') or []) or 'not measured'
    final = registry.get('final', {})
    overlap = registry.get('max_measured_final_dot_overlap_within_3px')
    rho = registry.get('max_measured_surface_rank_correlation')
    paired = h.get('paired_control', {})
    dci = ' to '.join(f(x) for x in paired.get('ci95') or [])
    controls = json.loads((ROOT / 'docs/ced-holdout.json').read_text())['summary']['scores'] if (ROOT / 'docs/ced-holdout.json').exists() else {}
    control = controls.get('magnetic_control', {})
    download = (f'<a class="button" download href="{escape(a["file"])}">↓ Download research GeoTIFF</a>'
                f'<div style="text-align:center;margin-top:12px"><a download href="{escape(a["zip"])}">Single-TIFF ZIP</a> · <a href="{escape(a["receipt"])}">Format receipt</a></div>') if a else '<p>No new TIFF exists for this run. No fake download is offered.</p>'
